def mark_characters_already_in_play(apps, schema_editor):
    """Set ``entered_play_at`` for characters that entered play before it (#803).

    The rule the code applies from now on, read over the stored records: a
    complete character (six scores and a Fatigue roll) seated in a battle that
    left its lobby, or attached to a Games Master session with a completed
    turn that ran a campaign action or recorded a house ruling. On a copy of
    the main checkout's local database, 2026-09-29: 11 of 122 characters.
    """
    Character = apps.get_model("characters", "Character")
    GMTurnRecord = apps.get_model("gm", "GMTurnRecord")
    complete = Character.objects.filter(
        fatigue_roll__isnull=False,
        **{f"{name}__isnull": False for name in ATTRIBUTES},
    )
    played_sessions = {
        record.session_id
        for record in GMTurnRecord.objects.filter(
            outcome="ok", session__isnull=False
        ).only("session_id", "procedures")
        if any(
            isinstance(frame, dict)
            and frame.get("ran")
            and frame.get("kind") in PLAY_ACTIONS
            for frame in (record.procedures or [])
        )
    }
    seated = complete.filter(battle_combatants__battle__status__in=STARTED)
    played = complete.filter(gm_sessions__pk__in=played_sessions)
    ids = set(seated.values_list("pk", flat=True)) | set(
        played.values_list("pk", flat=True)
    )
    Character.objects.filter(pk__in=ids).update(entered_play_at=timezone.now())


